.gmg-root{position:absolute;inset:0;overflow:hidden;background:var(--wa-bg, #05050a);z-index:5;font-family:"Pretendard Variable","Pretendard","Malgun Gothic",-apple-system,system-ui,sans-serif;font-size:16px;font-weight:400;font-style:normal;line-height:normal;letter-spacing:normal;color:var(--wa-text, #fff);text-align:left;text-transform:none;word-spacing:normal;-webkit-font-smoothing:antialiased}
.gmg-root,.gmg-root *,.gmg-root *::before,.gmg-root *::after{box-sizing:border-box}
.gmg-root *{margin:0;padding:0;border:0 solid transparent;background:none;font:inherit;color:inherit;text-decoration:none}
.gmg-root img{display:block;border:0;max-width:none}
.gmg-root > [data-node-id]{will-change:transform}
.gmg-root [hidden]{display:none!important}
.gmg-root [data-sh-theme="light"]{display:none!important}
.gmg-root[data-theme="light"] [data-sh-theme="light"]{display:block!important}
.gmg-root[data-theme="light"] [data-sh-theme="dark"]{display:none!important}
.gmg-root .nI3070_1950_34_1017{align-content:stretch;display:flex;gap:10px;height:24px;align-items:center;justify-content:center;padding-left:17px;padding-right:17px;padding-top:6px;padding-bottom:6px;position:relative;flex-shrink:0}
.gmg-root .nI3070_1950_34_1017_347_43003{position:absolute;height:24px;left:0;top:0;width:57px}
.gmg-root .x7{position:absolute;display:block;inset:0;max-width:none;width:100%;height:100%}
.gmg-root .nI3070_1950_34_1017_347_43006{text-box-edge:cap alphabetic;text-box-trim:trim-both;word-break:break-word;display:flex;flex-direction:column;font-family:"Pretendard Variable","Pretendard","Malgun Gothic",-apple-system,system-ui,sans-serif;font-weight:400;justify-content:center;line-height:0;font-style:normal;position:relative;flex-shrink:0;font-size:13px;color:color-mix(in srgb, var(--wa-text, rgb(255 255 255)) 90%, transparent);text-align:center;white-space:nowrap;width:23px;height:9px}
.gmg-root .nI3070_1950_34_1017_347_43006>p:first-of-type:last-of-type,.gmg-root .nI3070_1950_34_1017_347_43006>span:first-of-type:last-of-type{text-box-trim:trim-both;text-box-edge:cap alphabetic}
.gmg-root .x8{line-height:1}
.gmg-root [data-name="Tab/GAS#1 (Active)"] + [data-name="Tab/GAS#1 (Active)"]{display:none!important}
.gmg-root[data-theme="light"] [data-name="Badge/Gas Level"] p{color:var(--wa-text, #fff)!important}
.gmg-root[data-theme="light"] [data-name="Badge/Critical"] p,.gmg-root[data-theme="light"] [data-name^="status-critical"] p,.gmg-root[data-theme="light"] [data-name="Count/Critical"] p{color:var(--wa-danger, #ad152d)!important;font-weight:600;white-space:nowrap}
.gmg-root[data-theme="light"] [data-name="Badge/Major"] p,.gmg-root[data-theme="light"] [data-name^="status-major"] p,.gmg-root[data-theme="light"] [data-name="Count/Major"] p{color:var(--wa-warn, #ad4d00)!important;font-weight:600;white-space:nowrap}
.gmg-root[data-theme="light"] [data-name="Badge/Minor"] p,.gmg-root[data-theme="light"] [data-name^="status-minor"] p,.gmg-root[data-theme="light"] [data-name="Count/Minor"] p{color:var(--wa-warn, #856000)!important;font-weight:600;white-space:nowrap}
.gmg-root[data-theme="light"] [data-name="Badge/Warning"] p,.gmg-root[data-theme="light"] [data-name^="status-warning"] p,.gmg-root[data-theme="light"] [data-name="Count/Warning"] p{color:var(--wa-point, #1356b3)!important;font-weight:600;white-space:nowrap}
.gmg-root[data-theme="light"] [data-name="Badge/Normal"] p,.gmg-root[data-theme="light"] [data-name^="status-normal"] p,.gmg-root[data-theme="light"] [data-name="Count/Normal"] p{color:var(--wa-text-sub, #4b5868)!important;font-weight:600;white-space:nowrap}
.gmg-root[data-theme="light"] [data-name^="Button/"]:not([data-name="Button/Close"]):not([data-name="Button/Ack"]) p{color:var(--wa-text, #fff)!important}
.gmg-root[data-theme="light"]{color:var(--wa-point, #15253a)}
.gmg-root[data-theme="light"] .nI3070_1950_34_1017_347_43006{color:var(--wa-point, #15253a)}
